use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let a = arr[0].as_u64().unwrap();
    let b = arr[1].as_u64().unwrap();
    let mut count = 0;
    let mut x = a;
    let mut y = b;
    while x != 0 || y != 0 {
        if x & 1 != y & 1 {
            count += 1;
        }
        x >>= 1;
        y >>= 1;
    }
    Value::from(count)
}
